import React, { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import axios from 'axios'

export const PurchaseOrderDetailScreen = () => {
  const { id } = useParams<{ id: string }>()
  const navigate = useNavigate()

  const [poDetails, setPoDetails] = useState<any>(null)
  const [items, setItems] = useState<any[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const API_BASE_URL = process.env.REACT_APP_API_URL || 'https://celerant-backend.agreeablemeadow-3f37c30d.westus2.azurecontainerapps.io'

  useEffect(() => {
    loadPODetails()
  }, [id])

  const loadPODetails = async () => {
    if (!id) return

    setLoading(true)
    setError(null)

    try {
      const response = await axios.get(`${API_BASE_URL}/api/purchase-orders/${id}`)
      setPoDetails(response.data)

      // Also load the items for this PO
      const itemsResponse = await axios.get(`${API_BASE_URL}/api/purchase-orders/${id}/items`)
      setItems(itemsResponse.data || [])
    } catch (err: any) {
      setError(
        err.response?.data?.detail || 
        err.message || 
        'Failed to load purchase order details'
      )
    } finally {
      setLoading(false)
    }
  }

  const handleBackToList = () => {
    navigate('/purchase-orders')
  }

  const handleReceiveItems = () => {
    navigate(`/receiving?poNumber=${poDetails?.po_number}`)
  }

  if (loading || !id) {
    return (
      <div className="screen-container">
        <div className="screen-header">
          <h1 className="screen-title">Purchase Order Details</h1>
        </div>
        <div className="card">
          <div className="card-body text-center py-4">
            <p>Loading purchase order details...</p>
          </div>
        </div>
      </div>
    )
  }

  if (!poDetails) {
    return (
      <div className="screen-container">
        <div className="screen-header">
          <h1 className="screen-title">Purchase Order Details</h1>
          <button 
            className="btn-secondary"
            onClick={handleBackToList}
          >
            Back to List
          </button>
          </div>
        <div className="alert alert-error">
          {error || 'Purchase order not found'}
        </div>
      </div>
    )
  }

  return (
    <div className="screen-container">
      <div className="screen-header">
        <h1 className="screen-title">Purchase Order Details</h1>
        <div className="screen-actions">
          <button 
            className="btn-secondary"
            onClick={handleBackToList}
          >
            Back to List
          </button>
          {!poDetails.is_closed && (
            <button 
              className="btn-primary"
              onClick={handleReceiveItems}
            >
              Receive Items
            </button>
          )}
        </div>
      </div>

      <div className="card">
        <div className="card-header">
          <h2 className="card-title">PO Information</h2>
        </div>
        <div className="card-body">
          <div className="row">
            <div className="col-md-4">
              <p><strong>PO Number:</strong> {poDetails.po_number}</p>
              <p><strong>Order Date:</strong> {poDetails.order_date}</p>
              <p><strong>Expected Date:</strong> {poDetails.expected_date}</p>
            </div>
            <div className="col-md-4">
              <p><strong>Vendor:</strong> {poDetails.vendor_name}</p>
              <p><strong>Vendor Contact:</strong> {poDetails.vendor_contact}</p>
              <p><strong>Shipping Method:</strong> {poDetails.shipping_method}</p>
            </div>
            <div className="col-md-4">
              <p><strong>Status:</strong> 
                <span 
                  className={`status-badge ${poDetails.status.toLowerCase()}`}
                >
                  {poDetails.status}
                </span>
              </p>
              <p><strong>Currency:</strong> {poDetails.currency}</p>
              <p><strong>Total Amount:</strong> ${parseFloat(poDetails.total_amount || 0).toFixed(2)}</p>
            </div>
          </div>
        </div>
      </div>

      {items.length > 0 && (
        <>
          <div className="card">
            <div className="card-header">
              <h2 className="card-title">PO Items ({items.length})</h2>
            </div>
            <div className="card-body">
              <table className="data-table">
                <thead>
                  <tr>
                    <th>Item ID</th>
                    <th>Description</th>
                    <th>Quantity</th>
                    <th>Unit Cost</th>
                    <th>Line Total</th>
                    <th>Received</th>
                    <th>Remaining</th>
                  </tr>
                </thead>
                <tbody>
                  {items.map((item: any, index: number) => {
                    const lineTotal = parseFloat(item.quantity) * parseFloat(item.unit_cost || 0)
                    const received = item.quantity_received || 0
                    const remaining = parseFloat(item.quantity) - received

                    return (
                      <tr key={index}>
                        <td>{item.item_id}</td>
                        <td>{item.description}</td>
                        <td>{item.quantity}</td>
                        <td>${parseFloat(item.unit_cost || 0).toFixed(2)}</td>
                        <td>{received}</td>
                        <td>{remaining.toFixed(0)}</td>
                      </tr>
                    )
                  })}
                </tbody>
              </table>
            </div>
          </div>

          {!poDetails.is_closed && (
            <div className="card">
              <div className="card-header">
                <h2 className="card-title">PO Summary</h2>
              </div>
              <div className="card-body">
                <p><strong>Subtotal:</strong> ${parseFloat(poDetails.subtotal || 0).toFixed(2)}</p>
                <p><strong>Tax Amount:</strong> ${parseFloat(poDetails.tax_amount || 0).toFixed(2)}</p>
                <p><strong>Shipping Cost:</strong> ${parseFloat(poDetails.shipping_cost || 0).toFixed(2)}</p>
                <p><strong>Total Amount:</strong> ${parseFloat(poDetails.total_amount || 0).toFixed(2)}</p>
              </div>
            </div>
          )}
        </>
      )}
    </div>
  )
}
